def automorphicNumbersUpTo(n):
    residues = [0]
    out = []
    for k in range(1, 11):
        mod = 10 ** k
        step = 10 ** (k - 1)
        if step > n:
            break
        nxt = []
        for y in residues:
            for d in range(10):
                x = y + d * step
                if (x * x - x) % mod == 0:
                    nxt.append(x)
        residues = nxt
        for x in residues:
            if step <= x < mod and x <= n:
                out.append(x)
    return sorted(out)
